local _, WFJ = ...
WFJ.Data.add("spell", {
  [400009] = { "Mossa risolutiva a distanza che infligge danni per punto combo, aumentati dalla potenza d'attacco, e stordisce il bersaglio:\n\n$N1 punto: $N2 danni, $D1 di stordimento\n $N4 punti: $N5 danni, $D2 di stordimento\n $N7 punti: $N8 danni, $D3 di stordimento\n $N10 punti: $N11 danni, $D4 di stordimento\n $N13 punti: $N14 danni, $D5 di stordimento\n\nTempo di recupero condiviso con ⟦Kidney Shot=Colpo ai Reni⟧.", "Stordito.", 0x658894d6, 0x27f95286, "uu" },
  [400012] = { "Mossa risolutiva che aumenta la probabilità di parata del $N1% e conferisce $N2 potenza d'attacco per ogni punto di abilità in Difesa oltre $N3. Dura di più per ogni punto combo:\n\n$N4 punto: $N5 s\n $N6 punti: $N7 s\n $N8 punti: $N9 s\n $N10 punti: $N11 s\n $N12 punti: $N13 s", { "Probabilità di parata aumentata del $N1%.  Danni fisici subiti ridotti del $N2%.", "Probabilità di parata aumentata del $N1%. ", shape = { "2/0", "1/0" } }, 0xc4b7b86b, 0x43cd9880, "uu" },
  [400014] = { "Subisci il $N1% di danni fisici in meno mentre l'effetto di Lame Danzanti è attivo, ridotti di un ulteriore $N2% ogni $N3 punti di abilità in Difesa oltre $N4. Inoltre, la tua probabilità di schivata viene moltiplicata per il $N5%, la tua probabilità di subire colpi critici dagli attacchi in mischia è ridotta del $N6%, infliggi il $N7% di danni in meno, la minaccia generata da tutte le tue azioni aumenta enormemente e la tua abilità Finta è sostituita da Tease, che provoca il bersaglio inducendolo ad attaccarti.\n\n$I1\nProvoca il bersaglio, inducendolo ad attaccarti, ma non ha effetto se il bersaglio ti sta già attaccando.", nil, 0x1c18a384, nil, "um" },
  [400015] = { nil, { "Salute aumentata del $N1% del massimo e Armatura degli oggetti aumentata del $N2%.", "Salute aumentata del $N1% del massimo.", shape = { "2/0", "1/0" } }, nil, 0xaae7a7ef, "mu" },
  [400016] = { "Ogni volta che schivi o pari, la tua salute aumenta del $N1%, effetto che si accumula fino a $N2 volte.", nil, 0xae43c6e0, nil, "um" },
  [400023] = { "Qualsiasi attacco che altrimenti ti ucciderebbe riduce invece la tua salute al $N1% del massimo. Inoltre, tutti i danni subiti sono ridotti fino al $N2% per $D1. Questo effetto non può verificarsi più di una volta al minuto.", "Ha ingannato la morte di recente.", 0xc4a282b0, 0xb990c06a, "uu" },
  [400024] = { "Qualsiasi attacco che altrimenti ti ucciderebbe riduce invece la tua salute al $N1% del massimo. Inoltre, tutti i danni subiti sono ridotti fino al $N2% per $D1. Questo effetto non può verificarsi più di una volta al minuto.", "Tutti i danni subiti ridotti del $N1%.", 0xc4a282b0, 0xbd0656aa, "uu" },
  [400029] = { "Tenta di passare attraverso le ombre per riapparire alle spalle del nemico e aumenta la velocità di movimento del $N1% per $D1.", nil, 0x8a1e673d, nil, "um" },
  [400031] = { "Ottieni l'abilità Assalto d'Ombra:\n\n$I1\nTi teletrasporti alle spalle del bersaglio e lo colpisci, infliggendo il $N1% dei danni dell'arma. Utilizzabile solo in Furtività. Fornisce $N2 punti combo.", nil, 0x0e7cfb68, nil, "um" },
  [400032] = { "Ottieni l'abilità Lancio dello Shuriken:\n\n$I1\nLancia uno shuriken al nemico, infliggendo danni pari al $N1% della tua potenza d'attacco, e colpisce anche fino a $N2 bersagli aggiuntivi vicini. Fornisce $N3 punti combo per ogni bersaglio colpito.", nil, 0x06d480f9, nil, "um" },
  [400033] = { "Ottieni l'abilità In Mezzo agli Occhi:\n\n$I1\nMossa risolutiva a distanza che infligge danni per punto combo, aumentati dalla potenza d'attacco, e stordisce il bersaglio:\n\n$N1 punto: $N2 danni, $D1 di stordimento\n $N4 punti: $N5 danni, $D2 di stordimento\n $N7 punti: $N8 danni, $D3 di stordimento\n $N10 punti: $N11 danni, $D4 di stordimento\n $N13 punti: $N14 danni, $D5 di stordimento\n\nTempo di recupero condiviso con Colpo ai Reni.", nil, 0x5526d457, nil, "um" },
  [400037] = { "Ottieni l'abilità Passo nell'Ombra:\n\n$I1\nTenta di passare attraverso le ombre per riapparire alle spalle del nemico e aumenta la velocità di movimento del $N1% per $D1.", nil, 0x954f9cf0, nil, "um" },
  [400038] = { "Ottieni l'abilità Lame Danzanti:\n\n$I1\nMossa risolutiva che aumenta la probabilità di parata del $N1% e conferisce $N2 potenza d'attacco per ogni punto di abilità in Difesa oltre $N3. Dura di più per ogni punto combo:\n\n$N4 punto: $N5 s\n $N6 punti: $N7 s\n $N8 punti: $N9 s\n $N10 punti: $N11 s\n $N12 punti: $N13 s", nil, 0xb8f5f4cf, nil, "um" },
  [400039] = { "Ottieni l'abilità Just a Flesh Wound:\n\n$I1\nSubisci il $N1% di danni fisici in meno mentre l'effetto di Lame Danzanti è attivo, ridotti di un ulteriore $N2% ogni $N3 punti di abilità in Difesa oltre $N4. Inoltre, la tua probabilità di schivata viene moltiplicata per il $N5%, la tua probabilità di subire colpi critici dagli attacchi in mischia è ridotta del $N6%, infliggi il $N7% di danni in meno, la minaccia generata da tutte le tue azioni aumenta enormemente e la tua abilità Finta è sostituita da Tease, che provoca il bersaglio inducendolo ad attaccarti.\n\n$I2\nProvoca il bersaglio, inducendolo ad attaccarti, ma non ha effetto se il bersaglio ti sta già attaccando.", nil, 0x05da1105, nil, "um" },
  [400040] = { "Ottieni l'abilità Rolling with the Punches:\n\n$I1\nOgni volta che schivi o pari, la tua salute aumenta del $N1%, effetto che si accumula fino a $N2 volte.", nil, 0xd54c7878, nil, "um" },
  [400080] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Miscela Letale:\n\n$I1\nConferisce diversi miglioramenti ai tuoi veleni:\n\nQuando infliggi un qualsiasi altro veleno a un bersaglio, gli infliggi anche Veleno Mortale.\n\nSe alla tua arma non è applicato alcun veleno, ha una probabilità di attivare Veleno Istantaneo come se Veleno Istantaneo fosse applicato.\n\nVeleno Mortale e Veleno Istantaneo ora traggono più danni dalla tua potenza d'attacco.\n\nIl tuo Veleno Mortale ora può essere attivo sui bersagli colpiti dal Veleno Mortale di un altro Ladro.", nil, 0x1a66a12e, nil, "um" },
  [400081] = { "Incidi sui tuoi gambali la runa In Mezzo agli Occhi:\n\n$I1\nMossa risolutiva a distanza che infligge danni per punto combo, aumentati dalla potenza d'attacco, e stordisce il bersaglio:\n\n$N1 punto: $N2 danni, $D1 di stordimento\n $N4 punti: $N5 danni, $D2 di stordimento\n $N7 punti: $N8 danni, $D3 di stordimento\n $N10 punti: $N11 danni, $D4 di stordimento\n $N13 punti: $N14 danni, $D5 di stordimento\n\nTempo di recupero condiviso con Colpo ai Reni.", nil, 0x7fe6c87f, nil, "um" },
  [400082] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Just a Flesh Wound:\n\n$I1\nSubisci il $N1% di danni fisici in meno mentre l'effetto di Lame Danzanti è attivo, ridotti di un ulteriore $N2% ogni $N3 punti di abilità in Difesa oltre $N4. Inoltre, la tua probabilità di schivata viene moltiplicata per il $N5%, la tua probabilità di subire colpi critici dagli attacchi in mischia è ridotta del $N6%, infliggi il $N7% di danni in meno, la minaccia generata da tutte le tue azioni aumenta enormemente e la tua abilità Finta è sostituita da Tease, che provoca il bersaglio inducendolo ad attaccarti.\n\n$I2\nProvoca il bersaglio, inducendolo ad attaccarti, ma non ha effetto se il bersaglio ti sta già attaccando.", nil, 0xd37806b5, nil, "um" },
  [400093] = { "Incidi sui tuoi stivali la runa Rolling with the Punches:\n\n$I1\nOgni volta che schivi o pari, la tua salute aumenta del $N1%, effetto che si accumula fino a $N2 volte.", nil, 0xdc8b0d48, nil, "um" },
  [400094] = { "Incidi sui tuoi guanti la runa Mutilazione:\n\n$I1\nAttacca istantaneamente con entrambe le armi, infliggendo il $N1% dei danni dell'arma più $N2 danni aggiuntivi con ciascuna arma. Danni aumentati del $N3% contro i bersagli avvelenati. Fornisce $N4 punti combo.", nil, 0xb45a10bc, nil, "um" },
  [400095] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Estrazione Rapida:\n\n$I1\nEstrai l'arma a distanza e scocchi un tiro rapido contro un nemico, infliggendo i normali danni dell'arma a distanza e riducendo la velocità di movimento del bersaglio del $N1% per $D1. Fornisce $N3 punti combo.\n\nEstrazione Rapida beneficia di tutti i talenti e gli effetti che si attivano da Assalto Funesto o lo modificano.", nil, 0x0baef149, nil, "um" },
  [400096] = { "Incidi sulla tua cintura la runa Lancio dello Shuriken:\n\n$I1\nLancia uno shuriken al nemico, infliggendo danni pari al $N1% della tua potenza d'attacco, e colpisce anche fino a $N2 bersagli aggiuntivi vicini. Fornisce $N3 punti combo per ogni bersaglio colpito.", nil, 0xf3dd9623, nil, "um" },
  [400099] = { "Incidi sui tuoi gambali la runa Lame Danzanti:\n\n$I1\nMossa risolutiva che aumenta la probabilità di parata del $N1% e conferisce $N2 potenza d'attacco per ogni punto di abilità in Difesa oltre $N3. Dura di più per ogni punto combo:\n\n$N4 punto: $N5 s\n $N6 punti: $N7 s\n $N8 punti: $N9 s\n $N10 punti: $N11 s\n $N12 punti: $N13 s", nil, 0xde49cba0, nil, "um" },
  [400101] = { "Incidi sulla tua cintura la runa Passo nell'Ombra:\n\n$I1\nTenta di passare attraverso le ombre per riapparire alle spalle del nemico e aumenta la velocità di movimento del $N1% per $D1.", nil, 0x40b18911, nil, "um" },
  [400104] = { "Incidi sui tuoi gambali la runa Passo nell'Ombra:\n\n$I1\nTenta di passare attraverso le ombre per riapparire alle spalle del nemico e aumenta la velocità di movimento del $N1% per $D1.", nil, 0x70e32775, nil, "um" },
  [400105] = { "Incidi sui tuoi guanti la runa Assalto d'Ombra:\n\n$I1\nTi teletrasporti alle spalle del bersaglio e lo colpisci, infliggendo il $N1% dei danni dell'arma. Utilizzabile solo in Furtività. Fornisce $N2 punti combo.", nil, 0xdfa82ca8, nil, "um" },
  [400573] = { "Investe il bersaglio con un'esplosione di energia, infliggendo danni da arcano. Ogni volta che lanci ⟦Arcane Blast=Detonazione Arcana⟧, ottieni il $N1% del tuo Intelletto come danni magici e il costo in mana di ⟦Arcane Blast=Detonazione Arcana⟧ aumenta del $N2%. L'effetto si accumula fino a $N3 volte e dura $D1.", "Danni magici aumentati del $N1% dell'Intelletto e costo in mana di ⟦Arcane Blast=Detonazione Arcana⟧ aumentato del $N2%.", 0xc3693545, 0xdaf14ecf, "uu" },
  [400574] = { "Investe il bersaglio con un'esplosione di energia, infliggendo $N1 danni da arcano. Ogni volta che lanci ⟦Arcane Blast=Detonazione Arcana⟧, ottieni il $N2% del tuo Intelletto come danni magici e il costo in mana di ⟦Arcane Blast=Detonazione Arcana⟧ aumenta del $N3%. L'effetto si accumula fino a $N4 volte e dura $D1 dalla prima applicazione.", nil, 0x217b645e, nil, "um" },
  [400586] = { "Investe il bersaglio con un'esplosione di energia, infliggendo danni da arcano. Ogni volta che lanci ⟦Arcane Blast=Detonazione Arcana⟧, i danni di tutti gli altri incantesimi arcani aumentano del $N1% e il costo in mana di ⟦Arcane Blast=Detonazione Arcana⟧ aumenta del $N2%. L'effetto si accumula fino a $N3 volte e dura $D1.", "Danni degli incantesimi arcani diversi da ⟦Arcane Blast=Detonazione Arcana⟧ aumentati del $N1% e costo in mana di ⟦Arcane Blast=Detonazione Arcana⟧ aumentato del $N2%.", 0x9e46472c, 0x1647cf8e, "uu" },
  [400588] = { "Conferisce al tuo incantesimo ⟦Arcane Blast=Detonazione Arcana⟧ una probabilità del $N1%, e ai tuoi incantesimi Ira Arcana, Palla di Fuoco, Dardo di Gelo, ⟦Frost Blast=Detonazione del Gelo⟧ e Palla di Fuocogelo una probabilità del $N2%, di ridurre del $N3% la durata della canalizzazione del tuo prossimo incantesimo ⟦Arcane Missiles=Missili Arcani⟧, di ridurne il costo in mana del $N4% e di far partire i missili ogni $D1.", nil, 0x2f6c6d02, nil, "um" },
  [400589] = { "Riduce del $N1% la durata della canalizzazione del tuo prossimo incantesimo ⟦Arcane Missiles=Missili Arcani⟧, ne riduce il costo in mana del $N2% e fa partire i missili ogni $D1.", "Riduce del $N1% la durata della canalizzazione del tuo prossimo incantesimo ⟦Arcane Missiles=Missili Arcani⟧, ne riduce il costo in mana del $N2% e fa partire i missili ogni $D1.", 0xf8ba2f76, 0xf8ba2f76, "uu" },
  [400610] = { "Scaglia diversi missili contro il nemico bersaglio, infliggendo $N1 danni da arcano. Questo incantesimo ha anche una probabilità del $N2% di attivare Raffica di Missili.", nil, 0x5529aca1, nil, "um" },
  [400613] = { "Il bersaglio diventa una ⟦Living Bomb=Bomba Vivente⟧ e subisce $N1 danni da fuoco in $D1. Dopo $D2 o quando l'incantesimo viene dissolto, il bersaglio esplode infliggendo $N4 danni da fuoco a tutti i nemici entro $N5 m.\n\n⟦Living Bomb=Bomba Vivente⟧ beneficia di tutti i talenti e gli effetti che si attivano da Bruciatura o la modificano.", "Infligge $N1 danni da fuoco ogni $D1. Dopo $D2 o quando l'incantesimo viene dissolto, il bersaglio esplode infliggendo $N4 danni da fuoco a tutti i nemici entro $N5 m.", 0xc69cd4f9, 0x756c2ee6, "uu" },
  [400614] = { "Il bersaglio diventa una ⟦Living Bomb=Bomba Vivente⟧ e subisce $N1 danni da fuoco in $D1. Dopo $D2 o quando l'incantesimo viene dissolto, il bersaglio esplode infliggendo $N4 danni da fuoco a tutti i nemici entro $N5 m.", nil, 0xe9008f20, nil, "um" },
  [400615] = { "⟦Fire Blast=Detonazione di Fuoco⟧ infligge sempre un colpo critico, può essere lanciata mentre lanci un altro incantesimo e non è soggetta al tempo di recupero globale, ma il suo tempo di recupero aumenta a $D1.", nil, 0x63427631, nil, "um" },
  [400616] = { "Investe il nemico con $N1 danni da fuoco.", nil, 0x27fcb60f, nil, "um" },
  [400618] = { "Investe il nemico con $N1 danni da fuoco.", nil, 0x27fcb60f, nil, "um" },
  [400619] = { "Investe il nemico con $N1 danni da fuoco.", nil, 0x27fcb60f, nil, "um" },
  [400620] = { "Investe il nemico con $N1 danni da fuoco.", nil, 0x27fcb60f, nil, "um" },
  [400621] = { "Investe il nemico con $N1 danni da fuoco.", nil, 0x27fcb60f, nil, "um" },
  [400622] = { "Investe il nemico con $N1 danni da fuoco.", nil, 0x27fcb60f, nil, "um" },
  [400623] = { "Investe il nemico con $N1 danni da fuoco.", nil, 0x27fcb60f, nil, "um" },
  [400624] = { "I colpi critici non periodici di Palla di Fuoco, Palla di Fuocogelo, ⟦Fire Blast=Detonazione di Fuoco⟧ e Bruciatura riducono del $N2% il tempo di lancio della tua prossima Pirosfera lanciata entro $D1, effetto che si accumula fino a $N3 volte. ⟦Fire Blast=Detonazione di Fuoco⟧ conferisce un accumulo aggiuntivo ogni volta che infligge danni.", nil, 0xc5a6fbe5, nil, "um" },
  [400625] = { "I colpi critici non periodici di Palla di Fuoco, Palla di Fuocogelo, ⟦Fire Blast=Detonazione di Fuoco⟧ e Bruciatura riducono del $N2% il tempo di lancio della tua prossima Pirosfera lanciata entro $D1, effetto che si accumula fino a $N3 volte.", "Tempo di lancio del tuo prossimo incantesimo Pirosfera ridotto del $N1%.", 0xa37f53a1, 0xcadc3cd8, "uu" },
  [400640] = { "Infligge $N1 danni da gelo a un bersaglio nemico. Infligge il $N2% di danni in più ai bersagli congelati.", nil, 0x3353dc3d, nil, "um" },
  [400647] = { "Conferisce ai tuoi effetti di raggelamento una probabilità del $N1% di farti ottenere l'effetto Dita di Gelo, che fa trattare i tuoi prossimi $N2 incantesimi lanciati come se il bersaglio fosse congelato. Dura $D1.", nil, 0x57768bb5, nil, "um" },
  [400669] = { "Conferisce ai tuoi effetti di raggelamento una probabilità di farti ottenere l'effetto Dita di Gelo, che fa trattare i tuoi prossimi incantesimi lanciati come se il bersaglio fosse congelato. Dura $D1.", "I tuoi prossimi $N1 incantesimi trattano il bersaglio come se fosse congelato.", 0x1342e0b5, 0x67caf9f4, "uu" },
  [400670] = { "Conferisce ai tuoi effetti di raggelamento una probabilità di farti ottenere l'effetto Dita di Gelo, che fa trattare i tuoi prossimi incantesimi lanciati come se il bersaglio fosse congelato. Dura $D1.", "I tuoi incantesimi trattano il bersaglio come se fosse congelato.", 0x1342e0b5, 0x75f471db, "uu" },
  [400730] = { "Il tuo prossimo incantesimo Palla di Fuoco, Dardo di Geloincanto, Balefire Bolt o Palla di Fuocogelo è istantaneo e non costa mana.", "Il tuo prossimo incantesimo Palla di Fuoco, Dardo di Geloincanto, Balefire Bolt o Palla di Fuocogelo è istantaneo e non costa mana.", 0x32ad1d9a, 0x32ad1d9a, "uu" },
  [400731] = { "I tuoi incantesimi che infliggono danni da gelo con effetti di raggelamento hanno una probabilità del $N1% di rendere istantaneo e senza costo in mana il tuo prossimo incantesimo Palla di Fuoco, Dardo di Geloincanto, Balefire Bolt o Palla di Fuocogelo.", nil, 0xf1361684, nil, "um" },
  [400735] = { "Registra la posizione spazio-temporale del soggetto. Il $N1% di tutti i danni da arcano inflitti dall'incantatore viene convertito in cure cronomantiche su ciascuno dei bersagli attuali di Temporal Beacon dell'incantatore. Questa cura è ridotta del $N2% su sé stessi, e ridotta anche del $N3% quando i danni sono inflitti da incantesimi arcani che colpiscono più bersagli.", { "Registra la posizione del soggetto nel tempo e nello spazio. I danni inflitti dall'incantatore fanno ricevere a questo soggetto cure cronomantiche. Cura di $N1 salute al secondo.", "Registra la posizione del soggetto nel tempo e nello spazio. I danni inflitti dall'incantatore fanno ricevere a questo soggetto cure cronomantiche.", shape = { "1/0", "0/0" } }, 0x78299afb, 0x46517edc, "uu" },
})
